for title, x0, x1, y0, y1 in [("Crater/Scarp mid-north", 250, 370, 170, 290), ("Crater south-east", 260, 380, 30, 120)]:
    print(f"\n{title} (5m cells, # >0.36, + >0.33, * >0.28, . <=0.28):")
    for j in range(y1//5, y0//5 - 1, -1):
        row = []
        for i in range(x0//5, x1//5 + 1):
            ms = surf.cell_max_slope(i, j)
            if ms > 0.36: row.append('#')
            elif ms > 0.33: row.append('+')
            elif ms > 0.28: row.append('*')
            else: row.append('.')
        print(f"y={j*5:3d}|" + "".join(row))
